import{_t as e,it as t,n,rt as r}from"./chunks/framework.wWJFaB4n.js";var i=JSON.parse(`{"title":"Fieldset documentation","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"docs/guide/index.md"}`),a={name:`index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<div><h1 id="fieldset-documentation" tabindex="-1">Fieldset documentation <a class="header-anchor" href="#fieldset-documentation" aria-label="Permalink to “Fieldset documentation”">​</a></h1><p>Fieldset is a free, self-hostable platform for digital forms. Office staff design forms in the admin dashboard (<code>/admin</code>); field workers fill them in on a phone or tablet with the Field App (<code>/app</code>), also offline; the server numbers each submission, renders a branded PDF and runs workflows such as a review followed by an email to the customer.</p><p>These guides describe the current release. They are plain Markdown and work offline in a clone of the repository (ADR 0042, ADR 0094). Each release&#39;s guides are also published, with search and the interactive API reference, at <a href="https://beyerenrico.github.io/fieldset/" target="_blank" rel="noreferrer">beyerenrico.github.io/fieldset</a>.</p><h2 id="for-operators" tabindex="-1">For operators <a class="header-anchor" href="#for-operators" aria-label="Permalink to “For operators”">​</a></h2><table tabindex="0"><thead><tr><th>Guide</th><th>Contents</th></tr></thead><tbody><tr><td><a href="/fieldset/2.1/install">Install</a></td><td>The one-line install, local, domain and proxy modes, phones, mail capture, demo data, the instance directory, adopting a 1.0 install</td></tr><tr><td><a href="/fieldset/2.1/agent-guide">Agent guide</a></td><td>Recipes for AI agents and scripts: exact <code>fieldset</code> commands, the JSON fields to read, exit codes and recovery</td></tr><tr><td><a href="/fieldset/2.1/upgrade">Upgrade</a></td><td><code>fieldset upgrade</code> with its safety backup and automatic rollback, <code>fieldset rollback</code>, the Field App update</td></tr><tr><td><a href="/fieldset/2.1/backup-restore">Backup and restore</a></td><td>The backup schedule, encryption, drills, <code>fieldset restore</code>, moving to another server, chain epochs and the ledger</td></tr><tr><td><a href="/fieldset/2.1/configuration">Configuration</a></td><td><code>fieldset config</code> and every key, SMTP, what <code>fieldset</code> sets for you</td></tr><tr><td><a href="/fieldset/2.1/troubleshooting">Troubleshooting</a></td><td><code>fieldset status</code>, doctor and logs, failed commands, certificates, proxies, mail, PDFs, Field App sync, SSO, login throttling, the audit log</td></tr><tr><td><a href="/fieldset/2.1/archive/1.0-install">Archive: 1.0 checkout installs</a></td><td>The 1.0 guides for installations from a clone of the repository: <a href="/fieldset/2.1/archive/1.0-install">install</a>, <a href="/fieldset/2.1/archive/1.0-upgrade">upgrade</a>, <a href="/fieldset/2.1/archive/1.0-backup-restore">backup and restore</a>, <a href="/fieldset/2.1/archive/1.0-configuration">configuration</a>, <a href="/fieldset/2.1/archive/1.0-troubleshooting">troubleshooting</a>. Not for <code>fieldset</code> instances</td></tr></tbody></table><h2 id="for-organizations" tabindex="-1">For organizations <a class="header-anchor" href="#for-organizations" aria-label="Permalink to “For organizations”">​</a></h2><table tabindex="0"><thead><tr><th>Guide</th><th>Contents</th></tr></thead><tbody><tr><td><a href="/fieldset/2.1/admin-guide">Admin guide</a></td><td>Roles, members and groups, forms and both builders, designs, submissions and reviews, workflows, reports and dashboards, mail settings, single sign-on, API tokens, the audit log, retention, legal holds and personal data, the <code>/platform</code> operator panel</td></tr><tr><td><a href="/fieldset/2.1/field-app-guide">Field App guide</a></td><td>Installing the app, signing in, filling in and submitting forms, offline use and sync states, sending the PDF, reviews, keyboard use, personal data requests</td></tr></tbody></table><h2 id="for-developers-and-integrators" tabindex="-1">For developers and integrators <a class="header-anchor" href="#for-developers-and-integrators" aria-label="Permalink to “For developers and integrators”">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Contents</th></tr></thead><tbody><tr><td><a href="/fieldset/2.1/api">API and integrations</a></td><td>The REST API, the OpenAPI document at <code>/docs/api</code>, webhooks and signature verification</td></tr><tr><td><a href="/fieldset/2.1/field-app-api-v1">Field App API contract</a></td><td>The normative <code>/api/v1</code> contract</td></tr><tr><td><a href="../spec/form-definition/1.0/" target="_self">Fieldset Spec 1.0</a></td><td>The open JSON format for form definitions (MIT)</td></tr><tr><td><a href="https://github.com/beyerenrico/fieldset/tree/v2.1.0-rc.4/docs/adr" target="_blank" rel="noreferrer">Architecture decisions</a></td><td>One ADR per decision</td></tr><tr><td><a href="https://github.com/beyerenrico/fieldset/blob/v2.1.0-rc.4/README.md" target="_blank" rel="noreferrer">README</a></td><td>Development setup, demo data, checks</td></tr><tr><td><a href="/fieldset/2.1/changelog">Changelog</a> and <a href="https://github.com/beyerenrico/fieldset/tree/v2.1.0-rc.4/docs/releases" target="_blank" rel="noreferrer">release notes</a></td><td>What changed in each version</td></tr><tr><td><a href="https://github.com/beyerenrico/fieldset/blob/v2.1.0-rc.4/SECURITY.md" target="_blank" rel="noreferrer">Security policy</a></td><td>How to report vulnerabilities</td></tr></tbody></table><h2 id="terms-used-in-these-guides" tabindex="-1">Terms used in these guides <a class="header-anchor" href="#terms-used-in-these-guides" aria-label="Permalink to “Terms used in these guides”">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Organization</td><td>A company using the instance. Every record belongs to exactly one organization.</td></tr><tr><td>Form / form version</td><td>A form definition. Publishing creates an immutable version; submissions keep the version they were filled with.</td></tr><tr><td>Submission</td><td>One filled-in form, from draft to completed. The server assigns its number on submit.</td></tr><tr><td>Rendition</td><td>A PDF created from a submission with a design. PDFs are never changed; re-rendering creates a new one.</td></tr><tr><td>Design</td><td>Paper size, header, footer and layout of the PDFs, versioned like forms.</td></tr><tr><td>Workflow</td><td>A trigger, optional conditions and steps such as a review, an email or a webhook.</td></tr><tr><td>Field App</td><td>The installable web app for phones and tablets at <code>/app</code>.</td></tr></tbody></table></div>`,1)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};